export default class FloatingButtons{constructor(){this.advancedSearchPanel=document.getElementById("advancedSearchPanel"),this.floatingButtonContainer=document.getElementById("floatingButtonContainer"),this.menuToggleButton=document.getElementById("menuToggleButton"),this.fabMenu=document.getElementById("fabMenu"),this.menuItems=this.fabMenu?.querySelectorAll("[role='menuitem']"),this.menuOpen=!1,this.init()}init(){this.bindEvents(),this.align()}bindEvents(){queueMicrotask((()=>{this.menuToggleButton?.addEventListener("click",(()=>this.toggleMenu())),this.menuToggleButton?.addEventListener("keydown",(t=>{"Enter"!==t.key&&" "!==t.key||(t.preventDefault(),this.toggleMenu())})),document.addEventListener("keydown",(t=>{"Escape"===t.key&&(this.closeMenu(),this.menuToggleButton.focus())})),document.addEventListener("click",(t=>{this.fabMenu.contains(t.target)||this.menuToggleButton.contains(t.target)||this.closeMenu()}));document.querySelectorAll(".floatingButtons-menuButton").forEach((t=>{t.addEventListener("click",(()=>this.closeMenu()))})),window.addEventListener("resize",(()=>this.align())),window.addEventListener("orientationchange",(()=>this.align())),window.addEventListener("load",(()=>this.align()))}))}align(){this.advancedSearchPanel&&this.floatingButtonContainer&&queueMicrotask((()=>{const t=this.advancedSearchPanel.getBoundingClientRect(),e=window.pageXOffset||document.documentElement.scrollLeft,n=t.left+t.width/2+e;this.floatingButtonContainer.style.left=`${n}px`,this.floatingButtonContainer.style.transform="translateX(-50%)"}))}show(){this.floatingButtonContainer.style.visibility="visible"}hide(){this.floatingButtonContainer.style.visibility="hidden"}toggleMenu(){queueMicrotask((()=>{this.menuOpen=!this.menuOpen,this.fabMenu.style.display=this.menuOpen?"flex":"none",this.menuToggleButton.setAttribute("aria-expanded",String(this.menuOpen)),this.menuOpen?(this.menuItems[0]?.setAttribute("tabindex","0"),this.menuItems[0]?.focus()):this.menuItems?.forEach((t=>t.setAttribute("tabindex","-1")))}))}closeMenu(){this.menuOpen&&queueMicrotask((()=>{this.menuOpen=!1,this.fabMenu.style.display="none",this.menuToggleButton.setAttribute("aria-expanded","false"),this.menuItems?.forEach((t=>t.setAttribute("tabindex","-1")))}))}enableEditDeleteButtons(){document.getElementById("updateFilterButton")?.classList.remove("floatingButtons-disabled"),document.getElementById("deleteFilterButton")?.classList.remove("floatingButtons-disabled")}disableEditDeleteButtons(){document.getElementById("updateFilterButton")?.classList.add("floatingButtons-disabled"),document.getElementById("deleteFilterButton")?.classList.add("floatingButtons-disabled")}}
